/* Allt námsferlið er geymt í þessum vafra. Engin svör eru send til netþjóns. */
(function(){
  'use strict';
  const E=ExamEngine,bank=[...(globalThis.BPM_QUESTIONS||[]),...(globalThis.SYSTEMS_QUESTIONS||[]),...(globalThis.EXTRA_QUESTIONS||[])];
  const key='ferlar-prof-v1',main=document.getElementById('main');
  const names={bpm:'BPM og ferlagreining',systems:'Kerfishugsun',extra:'CJM og RPA'};
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let saved={},session=null,history=[],view='home',reviewFilter='all',reviewIndex=0,dialogAction=null;
  try{saved=JSON.parse(localStorage.getItem(key)||'{}');}catch{}
  if(E.validSession(saved.session))session=saved.session;
  if(Array.isArray(saved.history))history=saved.history.slice(0,8);
  let previous=Array.isArray(saved.previous)?saved.previous:[];
  // Heiti og talningar fylgja umferðinni svo stutti hamurinn vistist og birtist rétt.
  const modeName=mode=>({study:'Æfingahamur',exam:'Prófhamur',quick:'Stuttur hamur'}[mode]);
  const total=()=>session.questions.length;
  const countAnswered=()=>session?E.score(session).answered:0;
  function save(){try{localStorage.setItem(key,JSON.stringify({session,history,previous}));}catch{document.getElementById('storage-warning').hidden=false;}}
  function announce(text){document.getElementById('announcement').textContent=text;}
  function focusMain(){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
  function fmtTime(ms){const total=Math.max(0,Math.floor(ms/1000));return [Math.floor(total/3600),Math.floor(total/60)%60,total%60].map(n=>String(n).padStart(2,'0')).join(':');}
  function setView(next,focus=true){view=next;render();if(focus)focusMain();}
  function confirmAction(title,message,label,callback){document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-message').textContent=message;document.getElementById('dialog-ok').textContent=label;dialogAction=callback;document.getElementById('confirm-dialog').showModal();}
  document.getElementById('dialog-cancel').addEventListener('click',()=>document.getElementById('confirm-dialog').close());
  document.getElementById('dialog-ok').addEventListener('click',()=>{document.getElementById('confirm-dialog').close();const action=dialogAction;dialogAction=null;if(action)action();});
  function newExam(mode){const count=E.questionCount(mode);const action=()=>{const bytes=new Uint32Array(2);crypto.getRandomValues(bytes);const seed=Array.from(bytes,n=>n.toString(36)).join('-');const old=session?session.questions.map(q=>q.id):previous;session=E.newSession(bank,mode,seed,old);previous=old;save();setView('exam');announce(`Ný umferð með ${count} spurningum er hafin.`);};if(session&&!session.finishedAt)confirmAction('Hefja nýja umferð?',`Svör úr yfirstandandi umferð verða felld niður. Þú færð nýtt úrtak með ${count} spurningum.`,'Nýtt slembival',action);else action();}
  function finish(auto=false){if(!session||session.finishedAt)return;session.finishedAt=Date.now();session.autoSubmitted=auto;const score=E.score(session);history.unshift({at:session.finishedAt,mode:session.mode,correct:score.correct,total:score.total,percent:score.percent,seed:session.seed});history=history.slice(0,8);save();reviewFilter='all';reviewIndex=0;setView('results');announce(auto?'Tíminn er liðinn. Svörin hafa verið metin.':'Umferð lokið. Niðurstöður eru tilbúnar.');}
  function askFinish(){const n=total()-countAnswered();confirmAction('Skila umferð?',n?`${n} spurningum er ósvarað. Þær gefa 0 stig. Röng svör gefa engan frádrátt.`:'Öllum spurningum er svarað. Svörin verða læst og rökstudd yfirferð opnast.','Skila og sjá niðurstöðu',()=>finish());}
  function enforceDeadline(){if(session&&!session.finishedAt&&session.mode==='exam'&&E.timeLeft(session)===0){document.getElementById('confirm-dialog').close();dialogAction=null;finish(true);return true;}return false;}
  function home(){const score=session?E.score(session):null;return `
    ${session&&!session.finishedAt?`<div class="resume"><div><strong>Umferð í gangi</strong><p>${countAnswered()} af ${total()} svörum · ${session.mode==='exam'?'Prófhamur, tíminn heldur áfram':modeName(session.mode)} · Svörin þín hafa verið varðveitt.</p></div><button class="button" data-action="resume">Halda áfram</button></div>`:''}
    <section class="hero"><div><div class="eyebrow">Greining ferla og kerfa</div><h1>Skildu ferlið.<br>Æfðu þig fyrir prófið.</h1><p class="hero-intro">Beittu hugtökunum á ný dæmi, reiknaðu og lestu líkön. Veldu 10 eða 80 spurninga umferð úr námsefninu og lærðu af svörunum.</p><div class="hero-chips"><span class="chip"><strong>F1–F14</strong> og viðbótarefni</span><span class="chip">BPMN og orsakasamhengi</span><span class="chip">Enginn frádráttur</span></div></div>
    <section class="start-card" aria-labelledby="start-title"><div class="eyebrow">Ný umferð</div><h2 id="start-title">Hvernig viltu æfa?</h2><fieldset class="mode-options"><legend>Veldu ham</legend><label class="mode-option"><input type="radio" name="mode" value="study" checked><span><strong>Æfingahamur · 80 spurningar</strong><small>Án tímamarka. Skoðaðu rök eftir hvert svar.</small></span></label><label class="mode-option"><input type="radio" name="mode" value="quick"><span><strong>Stuttur hamur · 10 spurningar</strong><small>Stutt æfing án tímamarka, með skýringum eftir hvert svar.</small></span></label><label class="mode-option"><input type="radio" name="mode" value="exam"><span><strong>Prófhamur · 80 spurningar</strong><small>3 klst. Svör og skýringar birtast þegar þú skilar.</small></span></label></fieldset><button class="button" data-action="start">${session?'Nýtt slembival · 80 spurningar':'Hefja æfingu · 80 spurningar'}</button><p class="start-note">Eitt rétt svar við hverri spurningu. Hafðu vasareikni við höndina.</p></section></section>
    <section class="stat-row" aria-label="Um æfingarnar"><div class="stat"><strong>${bank.length}</strong><span>spurningar í bankanum</span></div><div class="stat"><strong>10 / 80</strong><span>spurningar í umferð</span></div><div class="stat"><strong>3 klst.</strong><span>tímamörk í prófham</span></div></section>
    <section><div class="section-heading"><h2>Allt efnið. Skýr áhersla á BPM.</h2><span class="small muted">Dreifing 80 spurninga umferðar</span></div><div class="coverage"><article><strong>60</strong><h3>BPM og ferlagreining</h3><p>F1–F10 og F13–F14. Líkön, uppgötvun, greining, endurhönnun og stjórnun.</p></article><article><strong>16</strong><h3>Kerfishugsun</h3><p>F11–F12 og CLD. Lykkjur, tafir, kerfishegðun og inngrip.</p></article><article><strong>4</strong><h3>CJM og RPA</h3><p>Vegferð viðskiptavinar og stafrænt vinnuafl.</p></article></div><p class="bank-footnote">Í 80 spurninga umferð eru að minnsta kosti 12 reikningsdæmi og 13 myndspurningar. Stutti hamurinn hefur 7 BPM-spurningar, 2 um kerfishugsun og 1 um CJM/RPA, þar af að minnsta kosti 2 reikningsdæmi og 2 myndspurningar. Dreifingin er valin fyrir þessar æfingar; hún er ekki staðfest vægi á lokaprófinu.</p></section>
    ${history.length?`<section class="history"><div class="section-heading"><h2>Nýlegar umferðir</h2><span class="small muted">Vistað í þessum vafra</span></div>${history.map((h,i)=>`<div class="history-row"><div><strong>${h.correct} / ${h.total}</strong><small>${new Date(h.at).toLocaleString('is-IS',{dateStyle:'medium',timeStyle:'short'})} · ${modeName(h.mode)}</small></div>${i===0&&session?.finishedAt&&h.seed===session.seed?'<button class="button secondary" data-action="results">Skoða yfirferð</button>':`<strong>${h.percent}%</strong>`}</div>`).join('')}</section>`:''}`;}
  function feedback(q){const a=session.answers[q.id],right=a===q.answer;return `<section class="feedback ${right?'':'wrong'}" aria-label="Yfirferð"><h3>${right?'Rétt svar':a===undefined?'Ósvarað':'Svarið þitt er rangt'}</h3><p><strong>Rétt svar: ${esc(q.options[q.answer])}</strong></p><p>${esc(q.explanation)}</p><div class="source">Heimild: ${esc(q.source.file)}${q.source.pages?.length?` · ${/\.pptx$/i.test(q.source.file)?'glæra':'PDF-blaðsíða'} ${q.source.pages.join(', ')}`:''}</div></section>`;}
  function questionCard(q,index,review=false){const revealed=review||!!session.revealed[q.id],chosen=session.answers[q.id],locked=review||revealed;
    return `<article class="question-card"><div class="question-top"><div class="question-meta"><span class="question-number">Spurning ${index+1}</span><span>${esc(names[q.group])}</span></div>${!review?`<button class="flag-button" data-action="flag" aria-pressed="${!!session.flags[q.id]}">${session.flags[q.id]?'★ Merkt':'☆ Merkja'}</button>`:''}</div><h2 class="stem" id="question-stem">${esc(q.stem)}</h2>${ExamDiagrams.render(q.diagram)}
    <fieldset class="answer-set" aria-describedby="question-stem"><legend>Veldu eitt rétt svar.</legend>${q.options.map((option,i)=>`<label class="option ${revealed&&i===q.answer?'correct':''} ${revealed&&i===chosen&&i!==q.answer?'incorrect':''}"><input type="radio" name="answer" value="${i}" ${chosen===i?'checked':''} ${locked?'disabled':''}><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span class="option-label">${esc(option)}</span>${revealed&&i===q.answer?'<span class="option-state">Rétt</span>':revealed&&i===chosen?'<span class="option-state">Þitt svar</span>':''}</label>`).join('')}</fieldset>
    ${!review?`<div class="question-actions">${session.mode!=='exam'&&!revealed?`<button class="button" data-action="check" ${chosen===undefined?'disabled':''}>Athuga svar</button>`:'<span class="small muted">'+(revealed?'Svarið er læst eftir yfirferð.':'Þú getur breytt svarinu fram að skilum.')+'</span>'}${!locked?`<button class="text-button" data-action="clear" ${chosen===undefined?'disabled':''}>Hreinsa svar</button>`:''}</div>`:''}${revealed?feedback(q):''}</article>`;}
  function navigator(review=false,indices=null){const chosen=indices||session.questions.map((_,i)=>i);return `<aside class="qnav" aria-label="Spurningayfirlit"><div class="qnav-title"><h2>${review?'Yfirferð':'Spurningayfirlit'}</h2><span>${review?chosen.length+' sp.':countAnswered()+'/'+total()}</span></div><div class="question-grid">${chosen.map(i=>{const q=session.questions[i],a=session.answers[q.id],answered=a!==undefined,current=review?i===indices[reviewIndex]:i===session.index;return `<button data-action="${review?'review-jump':'jump'}" data-index="${review?indices.indexOf(i):i}" class="${answered?'answered':''} ${current?'current':''} ${session.flags[q.id]?'flagged':''} ${review?(a===q.answer?'good':'wrong'):''}" aria-label="Spurning ${i+1}, ${review?(a===q.answer?'rétt':answered?'rangt':'ósvarað'):answered?'svarað':'ósvarað'}${session.flags[q.id]?', merkt':''}" ${current?'aria-current="step"':''}>${i+1}</button>`;}).join('')}</div>${!review?'<div class="nav-legend"><span>Svarað</span><span>Merkt til yfirferðar</span></div><button class="button secondary" data-action="finish">Skila umferð</button><p>Rangt svar gefur engan frádrátt. Reyndu að svara öllum spurningum.</p>':''}</aside>`;}
  function exam(){if(!session)return home();const answered=countAnswered();return `<div class="exam-header"><div><div class="eyebrow">${modeName(session.mode)}</div><h1>Ein spurning í einu.</h1><span class="small muted">${answered} af ${total()} svörum · ${Math.round(100*answered/total())}% lokið</span></div><div class="exam-tools"><button class="button secondary" data-action="new">Nýtt slembival</button><div class="timer" id="timer"><small>${session.mode==='exam'?'Tími eftir':'Tími frá upphafi'}</small><span id="clock">${fmtTime(session.mode==='exam'?E.timeLeft(session):Date.now()-session.startedAt)}</span></div></div></div><div class="progress" role="progressbar" aria-label="Svörun" aria-valuemin="0" aria-valuemax="${total()}" aria-valuenow="${answered}"><span style="width:${answered/total()*100}%"></span></div><div class="workspace"><section>${questionCard(session.questions[session.index],session.index)}<div class="page-controls"><button class="button secondary" data-action="prev" ${session.index===0?'disabled':''}>Fyrri spurning</button><span>${session.index+1} / ${total()}</span>${session.index===total()-1?'<button class="button" data-action="finish">Skila umferð</button>':'<button class="button" data-action="next">Næsta spurning</button>'}</div></section>${navigator()}</div>`;}
  function reviewIndices(){return session.questions.map((q,i)=>i).filter(i=>{const q=session.questions[i],a=session.answers[q.id];return reviewFilter==='wrong'?a!==undefined&&a!==q.answer:reviewFilter==='unanswered'?a===undefined:reviewFilter==='flagged'?!!session.flags[q.id]:true;});}
  function results(){if(!session?.finishedAt)return home();const s=E.score(session),indices=reviewIndices();reviewIndex=Math.min(reviewIndex,Math.max(0,indices.length-1));const index=indices[reviewIndex];return `<section class="results-header"><div><div class="eyebrow">Umferð lokið · ${modeName(session.mode)}</div><h1>${s.percent>=80?'Vel á veg komin.':'Skoðum hvað má styrkja.'}</h1><p>${session.autoSubmitted?'Tíminn rann út og umferðinni var skilað sjálfkrafa.':`Tími: ${fmtTime(Math.min(session.finishedAt-session.startedAt,session.mode==='exam'?10800000:Infinity))}`}</p></div><div class="score">${s.correct}<small> / ${s.total} · ${s.percent}%</small></div></section><div class="results-stats"><div class="result-stat"><strong>${s.correct}</strong><span>rétt svör</span></div><div class="result-stat"><strong>${s.wrong}</strong><span>röng svör</span></div><div class="result-stat"><strong>${s.unanswered}</strong><span>ósvarað</span></div></div><section class="result-categories"><h2>Árangur eftir efni</h2>${Object.entries(s.groups).sort((a,b)=>['bpm','systems','extra'].indexOf(a[0])-['bpm','systems','extra'].indexOf(b[0])).map(([g,v])=>`<div class="category-row"><span>${names[g]}</span><div class="progress"><span style="width:${v.correct/v.total*100}%"></span></div><strong>${v.correct} / ${v.total}</strong></div>`).join('')}<p class="small muted" style="margin-bottom:0">Eitt stig fyrir rétt svar. Enginn frádráttur. ${session.mode!=='exam'?'Í æfingaham endurspegla stigin svörin áður en skýring var opnuð.':''}</p></section><div class="review-toolbar"><div class="tabs" aria-label="Sía yfirferðar">${[['all','Allar'],['wrong','Röng svör'],['unanswered','Ósvarað'],['flagged','Merktar']].map(([k,label])=>`<button data-action="filter" data-filter="${k}" class="${reviewFilter===k?'active':''}" aria-pressed="${reviewFilter===k}">${label}</button>`).join('')}</div><button class="button" data-action="new">Nýtt slembival · ${total()}</button></div>${indices.length?`<div class="workspace"><section>${questionCard(session.questions[index],index,true)}<div class="page-controls"><button class="button secondary" data-action="review-prev" ${reviewIndex===0?'disabled':''}>Fyrri</button><span>${reviewIndex+1} / ${indices.length}</span><button class="button secondary" data-action="review-next" ${reviewIndex===indices.length-1?'disabled':''}>Næsta</button></div></section>${navigator(true,indices)}</div>`:'<div class="empty-review">Engar spurningar falla undir þessa síu.</div>'}`;}
  function sources(){const map=new Map();for(const q of bank){const s=map.get(q.source.file)||{n:0,lecture:new Set()};s.n++;s.lecture.add(q.lecture);map.set(q.source.file,s);}return `<section class="sources-page"><div class="eyebrow">Um æfingarnar</div><h1>Námsefnið ræður ferðinni.</h1><div class="source-summary"><p>Spurningarnar eru sjálfstæð æfingadæmi byggð á glærunum og viðbótarefninu í möppunni <strong>Prófsundirbúningur</strong>. Þetta eru ekki opinberar prófspurningar. Tilvísun við hvert svar sýnir hvaða efni styður skýringuna.</p><p>80 spurninga umferð inniheldur <strong>60 BPM-spurningar, 16 um kerfishugsun og 4 um CJM/RPA</strong>. Allir fyrirlestrar F1–F10 og F13–F14 eiga að minnsta kosti tvær spurningar í úrtakinu. Stutti hamurinn inniheldur 7 BPM-spurningar, 2 um kerfishugsun og 1 um CJM/RPA. Hann tekur mismunandi hluta námsefnisins fyrir í hverri umferð og tryggir að minnsta kosti 2 reikningsdæmi og 2 myndspurningar. Dreifingin er námsaðstoð og spáir ekki fyrir um nákvæmt vægi á lokaprófi.</p><p>Allar ${bank.length} spurningarnar eru fjölval með einu réttu svari. Raunprófið getur líka innihaldið rétt/rangt, fjölsvar, pörun og drag-and-drop. Nýtt slembival velur nýtt úrtak og stokkar valkostum; áður ónotaðar spurningar fá forgang miðað við síðustu umferð.</p><p>Í prófham rennur tíminn áfram þótt síðan sé lokuð. Prófið skilar sér sjálfkrafa þegar 3 klst. eru liðnar, eða þegar síðan er opnuð aftur eftir lok tímans. Þessi síða notar ekki SEB.</p><p style="margin-bottom:0">Svör og nýlegar niðurstöður vistast aðeins í þessum vafra. Heimildir birtast við yfirferð. Blaðsíðutölur vísa í röð síðna í PDF-skránni, sem getur verið önnur en prentað glærunúmer.</p></div><h2>Heimildir spurningabankans</h2><ul class="source-list">${Array.from(map).sort((a,b)=>a[0].localeCompare(b[0],'is',{numeric:true})).map(([file,v])=>`<li>${esc(file)}<small>${v.n} spurningar · ${esc([...v.lecture].join(', '))}</small></li>`).join('')}</ul><p class="muted small">Flæðirits- og deildarferilssniðmát voru einnig skoðuð; tengd hugtök eru studd með F2-glærunum. Heilar kennslubækur fylgdu ekki möppunni.</p><button class="button secondary" data-action="home">Aftur í yfirlit</button></section>`;}
  function render(){main.innerHTML=view==='exam'?exam():view==='results'?results():view==='sources'?sources():home();document.title=(view==='exam'?`Spurning ${session.index+1} af ${total()} · `:view==='results'?'Niðurstöður · ':'')+'Ferlar og kerfi';}
  document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;if(enforceDeadline())return;const action=b.dataset.action;switch(action){case'home':setView('home');break;case'sources':setView('sources');break;case'start':newExam(document.querySelector('input[name="mode"]:checked').value);break;case'resume':setView(session.finishedAt?'results':'exam');break;case'results':setView('results');break;case'new':newExam(session?.mode||'study');break;case'finish':askFinish();break;case'prev':session.index=Math.max(0,session.index-1);save();render();focusMain();break;case'next':session.index=Math.min(total()-1,session.index+1);save();render();focusMain();break;case'jump':session.index=Number(b.dataset.index);save();render();focusMain();break;case'flag':{const id=session.questions[session.index].id;session.flags[id]=!session.flags[id];save();render();break;}case'clear':{const id=session.questions[session.index].id;if(!session.revealed[id])delete session.answers[id];save();render();break;}case'check':{const q=session.questions[session.index];if(session.mode!=='exam'&&session.answers[q.id]!==undefined){session.revealed[q.id]=true;save();render();announce(session.answers[q.id]===q.answer?'Rétt svar. Skýring birtist fyrir neðan.':'Rangt svar. Skýring birtist fyrir neðan.');}break;}case'filter':reviewFilter=b.dataset.filter;reviewIndex=0;render();break;case'review-jump':reviewIndex=Number(b.dataset.index);render();document.querySelector('.question-card')?.scrollIntoView({block:'start'});break;case'review-prev':reviewIndex--;render();document.querySelector('.question-card')?.scrollIntoView({block:'start'});break;case'review-next':reviewIndex++;render();document.querySelector('.question-card')?.scrollIntoView({block:'start'});break;}});
  // Útvarpshnappar varðveita lyklaborðsstjórnun þegar svari er breytt.
  document.addEventListener('change',event=>{if(event.target.name==='mode'){document.querySelector('[data-action="start"]').textContent=`${session?'Nýtt slembival':'Hefja æfingu'} · ${E.questionCount(event.target.value)} spurningar`;return;}if(event.target.name!=='answer'||!session||session.finishedAt||enforceDeadline())return;const q=session.questions[session.index];if(session.revealed[q.id])return;const value=Number(event.target.value);session.answers[q.id]=value;save();render();document.querySelector(`input[name="answer"][value="${value}"]`)?.focus({preventScroll:true});});
  setInterval(()=>{if(enforceDeadline())return;if(view!=='exam'||!session)return;const ms=session.mode==='exam'?E.timeLeft(session):Date.now()-session.startedAt;const clock=document.getElementById('clock');if(clock)clock.textContent=fmtTime(ms);document.getElementById('timer')?.classList.toggle('urgent',session.mode==='exam'&&ms<600000);},1000);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')enforceDeadline();});
  if(bank.length<160){main.innerHTML='<p class="notice">Ekki tókst að hlaða öllum spurningabankanum. Endurhlaðið síðunni.</p>';return;}
  if(!enforceDeadline())render();
})();
